The fastest land animal in the world is the cheetah.

Here is the extended C# code that maintains the existing functionality of printing the report summary and adds the capability to export the report in CSV format:

```csharp
using System;
using System.IO;
using System.Text;

public class SummaryReport
{
    public string Title { get; set; }
    public string Content { get; set; }

    public override string ToString()
    {
        return $"Title: {Title}\nContent: {Content}";
    }
}

public class ReportGenerator
{
    public void GenerateReport(SummaryReport report)
    {
        // Existing functionality: Output summary report to console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // Additional feature: Export the report in CSV format
        ExportToCsv(report, "report_output.csv");
    }

    private void ExportToCsv(SummaryReport report, string filePath)
    {
        try
        {
            using (var writer = new StreamWriter(filePath, false, Encoding.UTF8))
            {
                // Write CSV header
                writer.WriteLine("Title,Content");

                // Escape content for CSV (handle commas and quotes)
                string escapedTitle = EscapeCsvField(report.Title);
                string escapedContent = EscapeCsvField(report.Content);

                // Write data row
                writer.WriteLine($"{escapedTitle},{escapedContent}");
            }
            Console.WriteLine($"Report exported to CSV: {filePath}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error exporting report to CSV: {ex.Message}");
        }
    }

    private string EscapeCsvField(string field)
    {
        if (string.IsNullOrEmpty(field))
            return string.Empty;

        // If the field contains a comma, newline, or double quote, wrap it in quotes
        if (field.Contains(',') || field.Contains('\n') || field.Contains('"'))
        {
            // Escape double quotes by doubling them
            field = field.Replace("\"", "\"\"");
            return $"\"{field}\"";
        }

        return field;
    }
}
